+@page "/board"
+@using sv_6be6cb075fda46cba0462c50cea66abf.Models
+@using sv_6be6cb075fda46cba0462c50cea66abf.Services
+@inject ITaskService TaskService
+@rendermode InteractiveServer
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h1>Kanban Board</h1>
+
+@if (_loading)
+{
+    <p><em>Loading tasks...</em></p>
+}
+else if (_error is not null)
+{
+    <div class="alert alert-danger">@_error</div>
+}
+else
+{
+    <!-- Stats Bar -->
+    <div class="stats-bar">
+        <span class="stat-item"><strong>Total:</strong> @_allTasks.Count</span>
+        <span class="stat-item"><strong>To Do:</strong> @GetColumnTasks("To Do").Count</span>
+        <span class="stat-item"><strong>In Progress:</strong> @GetColumnTasks("In Progress").Count</span>
+        <span class="stat-item"><strong>Done:</strong> @GetColumnTasks("Done").Count</span>
+        <span class="stat-item stat-overdue"><strong>Overdue:</strong> @_allTasks.Count(t => t.DueDate < DateTime.Today)</span>
+    </div>
+
+    <!-- Search Bar -->
+    <div class="search-bar">
+        <input type="text" class="form-control" placeholder="Search tasks by title..."
+               @bind="_searchText" @bind:event="oninput" />
+    </div>
+
+    <!-- Kanban Columns -->
+    <div class="board-container">
+        @foreach (var column in _columns)
+        {
+            var tasks = GetFilteredColumnTasks(column);
+            <div class="board-column">
+                <div class="column-header">
+                    <h3>@column <span class="badge">@tasks.Count</span></h3>
+                </div>
+
+                <div class="column-body">
+                    @foreach (var task in tasks)
+                    {
+                        <div class="task-card">
+                            <div class="task-title">@task.Title</div>
+                            <div class="task-assignee">@task.Assignee</div>
+                            <span class="priority-badge priority-@task.Priority.ToLowerInvariant()">@task.Priority</span>
+                            <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
+                            <div class="task-actions">
+                                @if (GetColumnIndex(column) > 0)
+                                {
+                                    <button class="btn btn-sm btn-outline-secondary"
+                                            @onclick="() => MoveTask(task.Id, _columns[GetColumnIndex(column) - 1])"
+                                            disabled="@_moving">
+                                        &larr; Move Left
+                                    </button>
+                                }
+                                @if (GetColumnIndex(column) < _columns.Length - 1)
+                                {
+                                    <button class="btn btn-sm btn-outline-secondary"
+                                            @onclick="() => MoveTask(task.Id, _columns[GetColumnIndex(column) + 1])"
+                                            disabled="@_moving">
+                                        Move Right &rarr;
+                                    </button>
+                                }
+                            </div>
+                        </div>
+                    }
+                </div>
+
+                @if (_addingToColumn == column)
+                {
+                    <div class="add-task-form">
+                        <input type="text" class="form-control" placeholder="Title" @bind="_newTitle" />
+                        <input type="text" class="form-control" placeholder="Assignee" @bind="_newAssignee" />
+                        <select class="form-control" @bind="_newPriority">
+                            <option value="High">High</option>
+                            <option value="Medium">Medium</option>
+                            <option value="Low">Low</option>
+                        </select>
+                        <input type="date" class="form-control" @bind="_newDueDate" />
+                        <div class="form-actions">
+                            <button class="btn btn-sm btn-primary" @onclick="() => SaveNewTask(column)" disabled="@_saving">Save</button>
+                            <button class="btn btn-sm btn-secondary" @onclick="CancelAdd">Cancel</button>
+                        </div>
+                    </div>
+                }
+                else
+                {
+                    <button class="btn btn-sm btn-outline-primary add-task-btn" @onclick="() => ShowAddForm(column)">
+                        + Add Task
+                    </button>
+                }
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private readonly string[] _columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> _allTasks = new();
+    private bool _loading = true;
+    private string? _error;
+    private string _searchText = string.Empty;
+    private bool _moving;
+    private bool _saving;
+
+    // Add-task form state
+    private string? _addingToColumn;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = "Medium";
+    private DateTime _newDueDate = DateTime.Today.AddDays(7);
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            _allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to load tasks: {ex.Message}";
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private List<TaskItem> GetColumnTasks(string status)
+        => _allTasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> GetFilteredColumnTasks(string status)
+        => _allTasks
+            .Where(t => t.Status == status)
+            .Where(t => string.IsNullOrWhiteSpace(_searchText)
+                        || t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase))
+            .ToList();
+
+    private int GetColumnIndex(string column) => Array.IndexOf(_columns, column);
+
+    private async Task MoveTask(int taskId, string newStatus)
+    {
+        _moving = true;
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = _allTasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                _allTasks[idx] = _allTasks[idx] with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to move task: {ex.Message}";
+        }
+        finally
+        {
+            _moving = false;
+        }
+    }
+
+    private void ShowAddForm(string column)
+    {
+        _addingToColumn = column;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd() => _addingToColumn = null;
+
+    private async Task SaveNewTask(string column)
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle))
+            return;
+
+        _saving = true;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
+            // The service creates tasks; we adjust status to match the column if needed.
+            var task = created.Status == column ? created : created with { Status = column };
+            if (task.Status != created.Status)
+            {
+                await TaskService.UpdateTaskStatusAsync(task.Id, column);
+            }
+            _allTasks.Add(task);
+            _addingToColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _error = $"Failed to create task: {ex.Message}";
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
