.stats-bar {
    display: flex;
    gap: 1.5rem;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat-item {
    font-size: 0.95rem;
}

.stat-overdue {
    color: #dc3545;
}

.search-bar {
    margin-bottom: 1rem;
    max-width: 400px;
}

.board-container {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    min-width: 250px;
    background: #f1f3f5;
    border-radius: 0.5rem;
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
}

.column-header h3 {
    font-size: 1.1rem;
    margin: 0 0 0.5rem 0;
}

.column-header .badge {
    background: #6c757d;
    color: #fff;
    border-radius: 999px;
    padding: 0.15em 0.55em;
    font-size: 0.8rem;
    vertical-align: middle;
}

.column-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 50px;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.4rem;
    padding: 0.65rem;
}

.task-title {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.task-assignee {
    font-size: 0.85rem;
    color: #6c757d;
    margin-bottom: 0.25rem;
}

.priority-badge {
    display: inline-block;
    padding: 0.1em 0.5em;
    border-radius: 0.25rem;
    font-size: 0.78rem;
    font-weight: 600;
    color: #fff;
    margin-bottom: 0.25rem;
}

.priority-high {
    background-color: #dc3545;
}

.priority-medium {
    background-color: #ffc107;
    color: #212529;
}

.priority-low {
    background-color: #28a745;
}

.task-due {
    font-size: 0.82rem;
    color: #495057;
    margin-bottom: 0.35rem;
}

.task-actions {
    display: flex;
    gap: 0.35rem;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    margin-top: 0.5rem;
    padding: 0.5rem;
    background: #fff;
    border: 1px dashed #adb5bd;
    border-radius: 0.4rem;
}

.form-actions {
    display: flex;
    gap: 0.35rem;
}

.add-task-btn {
    margin-top: 0.5rem;
    width: 100%;
}

